html:
{% import "costeo_yelke/templates/print/oc_yelke.html" as oc %}
{#- Diseño compartido: ver templates/print/oc_yelke.html -#}
{{ oc.estilos() }}
{{ oc.membrete_encabezado(letter_head, no_letterhead, print_settings) }}
<div class="pdf-container">

    <!-- BLOQUE DE INFORMACIÓN GENERAL -->
    <table class="info-table">
        <tr>
            <td class="client-section">
                <span class="section-title">Detalles Generales</span>
                <div class="info-line">
                    <strong>Cliente:</strong> {{ doc.cliente }}
                </div>
                <div class="info-line">
                    <strong>Fecha:</strong> {{ doc.get_formatted("fecha") }}
                </div>
                {% if doc.proyecto %}
                <div class="info-line">
                    <strong>Proyecto:</strong> {{ doc.proyecto }}
                </div>
                {% endif %}
                {% if doc.centro_de_costos %}
                <div class="info-line">
                    <strong>Centro de Costos:</strong> {{ doc.centro_de_costos }}
                </div>
                {% endif %}
            </td>
            <td class="quote-details">
                <span class="section-title">Información de Costeo</span>
                <div class="info-line">
                    <strong>Folio:</strong> {{ doc.name }}
                </div>
                <div class="info-line">
                    <strong>Compañía:</strong> {{ doc.compañia }}
                </div>
                {% if doc.almacen_materias_primas %}
                <div class="info-line">
                    <strong>Almacén MP:</strong> {{ doc.almacen_materias_primas }}
                </div>
                {% endif %}
                {% if doc.almacen_trabajo_en_proceso %}
                <div class="info-line">
                    <strong>Almacén WIP:</strong> {{ doc.almacen_trabajo_en_proceso }}
                </div>
                {% endif %}
            </td>
        </tr>
    </table>

    <!-- TABLA: COSTEO DE PRODUCTOS -->
    {% if doc.costeo_producto %}
    <h4 class="payment-terms-title" style="margin-top:20px;">Productos a Costear</h4>
    <table class="table items-table">
        <thead>
            <tr>
                <th class="text-center" width="5%">#</th>
                <th width="22%">Producto Terminado</th>
                <th class="text-right" width="8%">Cant.</th>
                <th class="text-right" width="11%">Costo Mat.</th>
                <th class="text-right" width="11%">Costo Serv.</th>
                <th class="text-right" width="11%">Costo Env.</th>
                <th class="text-right" width="11%">Overhead</th>
                <th class="text-right" width="11%">Costo Unit.</th>
                <th class="text-right" width="10%">P. Venta</th>
                <th class="text-right" width="10%">Margen</th>
            </tr>
        </thead>
        <tbody>
            {% for row in doc.costeo_producto %}
            <tr>
                <td class="text-center">{{ row.idx }}</td>
                <td>
                    <strong class="item-title">{{ row.finished_item or "-" }}</strong>
                </td>
                <td class="text-right">{{ row.qty or 0 }}</td>
                <td class="text-right">
                    {{ frappe.utils.fmt_money(row.material_cost or 0, currency=doc.currency or "MXN") }}
                </td>
                <td class="text-right">
                    {{ frappe.utils.fmt_money(row.services_cost or 0, currency=doc.currency or "MXN") }}
                </td>
                <td class="text-right">
                    {{ frappe.utils.fmt_money(row.shipping_cost or 0, currency=doc.currency or "MXN") }}
                </td>
                <td class="text-right">
                    {{ frappe.utils.fmt_money(row.overhead_amt or 0, currency=doc.currency or "MXN") }}
                    {% if row.overhead_pct %}
                        <div class="item-code">({{ row.overhead_pct }}%)</div>
                    {% endif %}
                </td>
                <td class="text-right">
                    <strong>{{ frappe.utils.fmt_money(row.total_unit_cost or 0, currency=doc.currency or "MXN") }}</strong>
                </td>
                <td class="text-right">
                    <strong style="color:#FF6B15;">
                        {{ frappe.utils.fmt_money(row.unit_sales_price or 0, currency=doc.currency or "MXN") }}
                    </strong>
                </td>
                <td class="text-right">
                    {% if row.margin_pct %}
                        <span style="color:#4CAF50;font-weight:700;">{{ "%.2f" | format(row.margin_pct) }}%</span>
                    {% else %}
                        -
                    {% endif %}
                </td>
            </tr>
            {% endfor %}
        </tbody>
    </table>
    {% endif %}

    <!-- TABLA: DETALLE DE COSTEO -->
    {% if doc.costeo_producto_detalle %}
    <div class="payment-terms" style="padding-top:15px;">
        <h4 class="payment-terms-title">Detalle de Costeo</h4>
        <table class="table payment-table">
            <thead>
                <tr>
                    <th width="5%">#</th>
                    <th width="15%">Producto</th>
                    <th width="20%">Concepto / Item</th>
                    <th class="text-center" width="12%">Tipo</th>
                    <th class="text-center" width="10%">Cant.</th>
                    <th class="text-right" width="13%">Precio Unit.</th>
                    <th class="text-right" width="13%">Total</th>
                    <th width="12%">Etapa</th>
                </tr>
            </thead>
            <tbody>
                {% for row in doc.costeo_producto_detalle %}
                <tr>
                    <td>{{ row.idx }}</td>
                    <td><strong>{{ row.finished_item or "-" }}</strong></td>
                    <td>
                        {% if row.item %}
                            <strong>{{ row.item }}</strong>
                        {% endif %}
                        {% if row.servicio %}
                            <div class="item-code">{{ row.servicio }}</div>
                        {% endif %}
                        {% if row.proveedor_servicio %}
                            <div class="item-code" style="color:#FF6B15;">{{ row.proveedor_servicio }}</div>
                        {% endif %}
                        {% if row.subensamblaje %}
                            <div class="item-code">Sub: {{ row.subensamblaje }}</div>
                        {% endif %}
                    </td>
                    <td class="text-center">
                        {% set tipo_val = row.concept_type or "" %}
                        {% if tipo_val == "Material" %}
                            <span style="background-color:#FFF3EC;color:#FF6B15;padding:2px 6px;border-radius:3px;font-size:9px;font-weight:600;">{{ tipo_val }}</span>
                        {% elif tipo_val == "Servicio" %}
                            <span style="background-color:#ECF5FF;color:#2196F3;padding:2px 6px;border-radius:3px;font-size:9px;font-weight:600;">{{ tipo_val }}</span>
                        {% elif tipo_val == "Subensamblaje" %}
                            <span style="background-color:#F3E5F5;color:#9C27B0;padding:2px 6px;border-radius:3px;font-size:9px;font-weight:600;">{{ tipo_val }}</span>
                        {% else %}
                            <span style="background-color:#F5F5F5;color:#666;padding:2px 6px;border-radius:3px;font-size:9px;font-weight:600;">{{ tipo_val or "-" }}</span>
                        {% endif %}
                    </td>
                    <td class="text-center">
                        {{ row.internal_qty or row.supplier_qty or "-" }}
                        {% if row.internal_uom %}
                            <div class="item-code">{{ row.internal_uom }}</div>
                        {% endif %}
                    </td>
                    <td class="text-right">
                        {{ frappe.utils.fmt_money(row.unit_price or 0, currency=doc.currency or "MXN") }}
                    </td>
                    <td class="text-right">
                        <strong>{{ frappe.utils.fmt_money(row.total or 0, currency=doc.currency or "MXN") }}</strong>
                    </td>
                    <td>{{ row.etapa or "-" }}</td>
                </tr>
                {% endfor %}
            </tbody>
        </table>
    </div>
    {% endif %}

    <!-- TABLA: ETAPAS DE COSTEO -->
    {% if doc.tabla_etapas_costeo %}
    <div class="payment-terms" style="padding-top:15px;">
        <h4 class="payment-terms-title">Etapas de Costeo</h4>
        <table class="table payment-table">
            <thead>
                <tr>
                    <th width="5%">#</th>
                    <th width="20%">Etapa</th>
                    <th width="20%">Servicio</th>
                    <th width="20%">Proveedor</th>
                    <th width="15%">Subensamblaje</th>
                    <th width="15%">Producto Term.</th>
                    <th class="text-right" width="15%">Precio</th>
                </tr>
            </thead>
            <tbody>
                {% for row in doc.tabla_etapas_costeo %}
                <tr>
                    <td>{{ row.idx }}</td>
                    <td><strong>{{ row.etapa or "-" }}</strong></td>
                    <td>{{ row.servicio or "-" }}</td>
                    <td>{{ row.proveedor or "-" }}</td>
                    <td>{{ row.subensamblaje or "-" }}</td>
                    <td>{{ row.producto_terminado or "-" }}</td>
                    <td class="text-right">
                        <strong>{{ frappe.utils.fmt_money(row.precio_servicio or 0, currency=doc.currency or "MXN") }}</strong>
                    </td>
                </tr>
                {% endfor %}
            </tbody>
        </table>
    </div>
    {% endif %}

    <!-- ========================= -->
    <!-- TOTALES: COSTO Y VENTA    -->
    <!-- ========================= -->
    {% if doc.costeo_producto %}
    {% set ns = namespace(total_costo=0, total_venta=0) %}
    {% for row in doc.costeo_producto %}
        {% set ns.total_costo = ns.total_costo + ((row.total_unit_cost or 0) * (row.qty or 1)) %}
        {% set ns.total_venta = ns.total_venta + (row.total_sales_price or 0) %}
    {% endfor %}
    {% set ns.total_margen = ns.total_venta - ns.total_costo %}
    {% set ns.margen_pct = ((ns.total_margen / ns.total_venta) * 100) | round(1) if ns.total_venta > 0 else 0 %}

    <div class="totals-section" style="margin-top:20px;">
        <table class="totals-double-table">
            <!-- Desglose por producto -->
            {% for row in doc.costeo_producto %}
            <tr>
                <td class="total-label" style="text-align:left;color:#888;font-size:9px;">
                    {{ row.finished_item or "Producto " ~ row.idx }}
                </td>
                <td class="total-value" style="font-size:9px;color:#888;">
                    Costo: {{ frappe.utils.fmt_money((row.total_unit_cost or 0) * (row.qty or 1), currency=doc.currency or "MXN") }}
                </td>
                <td class="total-value" style="font-size:9px;color:#FF6B15;">
                    Venta: {{ frappe.utils.fmt_money(row.total_sales_price or 0, currency=doc.currency or "MXN") }}
                </td>
            </tr>
            {% endfor %}

            <!-- Separador -->
            <tr class="total-costo-row">
                <td class="total-label total-costo-label" style="text-align:left;">COSTO TOTAL:</td>
                <td></td>
                <td class="total-value total-costo-value">
                    {{ frappe.utils.fmt_money(ns.total_costo, currency=doc.currency or "MXN") }}
                </td>
            </tr>

            <!-- Total Venta -->
            <tr class="total-venta-row">
                <td class="total-label total-venta-label" style="text-align:left;">TOTAL VENTA:</td>
                <td></td>
                <td class="total-value total-venta-value">
                    {{ frappe.utils.fmt_money(ns.total_venta, currency=doc.currency or "MXN") }}
                </td>
            </tr>

            <!-- Margen -->
            <tr class="margin-row">
                <td class="margin-label" style="text-align:left;padding:4px 8px;">
                    Margen de Utilidad:
                </td>
                <td></td>
                <td class="margin-value" style="padding:4px 8px;">
                    {{ frappe.utils.fmt_money(ns.total_margen, currency=doc.currency or "MXN") }}
                    ({{ ns.margen_pct }}%)
                </td>
            </tr>
        </table>
        <div style="clear:both;"></div>
    </div>

    <!-- ========================= -->
    <!-- GRÁFICA SVG               -->
    <!-- ========================= -->
    <div class="chart-section">
        <span class="chart-title">Análisis de Costos vs Ventas por Producto</span>
        <div class="chart-wrapper">

        {# Configuración del SVG #}
        {% set svg_width = 680 %}
        {% set svg_height = 220 %}
        {% set padding_left = 120 %}
        {% set padding_right = 20 %}
        {% set padding_top = 20 %}
        {% set padding_bottom = 50 %}
        {% set bar_area_width = svg_width - padding_left - padding_right %}
        {% set bar_area_height = svg_height - padding_top - padding_bottom %}
        {% set num_products = doc.costeo_producto | length %}
        {% set group_width = (bar_area_width / num_products) | int %}
        {% set bar_width = ((group_width * 0.35) | int) %}

        {# Calcular máximo para escala #}
        {% set ns2 = namespace(max_val=1) %}
        {% for row in doc.costeo_producto %}
            {% set costo_row = (row.total_unit_cost or 0) * (row.qty or 1) %}
            {% set venta_row = row.total_sales_price or 0 %}
            {% if costo_row > ns2.max_val %}{% set ns2.max_val = costo_row %}{% endif %}
            {% if venta_row > ns2.max_val %}{% set ns2.max_val = venta_row %}{% endif %}
        {% endfor %}
        {% set max_val = ns2.max_val * 1.15 %}

        <svg width="{{ svg_width }}" height="{{ svg_height }}" xmlns="http://www.w3.org/2000/svg"
             style="font-family:'Poppins',sans-serif;overflow:visible;">

            <!-- Fondo -->
            <rect x="0" y="0" width="{{ svg_width }}" height="{{ svg_height }}"
                  fill="#fdfdfd" rx="4"/>

            <!-- Líneas guía horizontales -->
            {% for i in range(5) %}
                {% set y_line = padding_top + (bar_area_height / 4 * i) | int %}
                {% set val_line = (max_val - (max_val / 4 * i)) | int %}
                <line x1="{{ padding_left }}" y1="{{ y_line }}"
                      x2="{{ svg_width - padding_right }}" y2="{{ y_line }}"
                      stroke="#f0f0f0" stroke-width="1"/>
                <text x="{{ padding_left - 6 }}" y="{{ y_line + 4 }}"
                      text-anchor="end" font-size="7" fill="#aaa">
                    {{ frappe.utils.fmt_money(val_line, currency=doc.currency or "MXN") }}
                </text>
            {% endfor %}

            <!-- Eje Y -->
            <line x1="{{ padding_left }}" y1="{{ padding_top }}"
                  x2="{{ padding_left }}" y2="{{ padding_top + bar_area_height }}"
                  stroke="#ddd" stroke-width="1"/>

            <!-- Eje X -->
            <line x1="{{ padding_left }}" y1="{{ padding_top + bar_area_height }}"
                  x2="{{ svg_width - padding_right }}" y2="{{ padding_top + bar_area_height }}"
                  stroke="#ddd" stroke-width="1"/>

            <!-- Barras por producto -->
            {% for row in doc.costeo_producto %}
                {% set costo_row = (row.total_unit_cost or 0) * (row.qty or 1) %}
                {% set venta_row = row.total_sales_price or 0 %}
                {% set group_x = padding_left + (group_width * loop.index0) + (group_width * 0.1) | int %}

                {# Barra Costo #}
                {% set bar_h_costo = ((costo_row / max_val) * bar_area_height) | int %}
                {% set bar_y_costo = padding_top + bar_area_height - bar_h_costo %}
                <rect x="{{ group_x }}" y="{{ bar_y_costo }}"
                      width="{{ bar_width }}" height="{{ bar_h_costo }}"
                      fill="#FFAA77" rx="2"/>
                <!-- Valor encima barra costo -->
                {% if bar_h_costo > 12 %}
                <text x="{{ group_x + bar_width / 2 | int }}" y="{{ bar_y_costo - 3 }}"
                      text-anchor="middle" font-size="6.5" fill="#FF6B15" font-weight="bold">
                    {{ frappe.utils.fmt_money(costo_row, currency=doc.currency or "MXN") }}
                </text>
                {% endif %}

                {# Barra Venta #}
                {% set bar_h_venta = ((venta_row / max_val) * bar_area_height) | int %}
                {% set bar_y_venta = padding_top + bar_area_height - bar_h_venta %}
                {% set bar_x_venta = group_x + bar_width + 4 %}
                <rect x="{{ bar_x_venta }}" y="{{ bar_y_venta }}"
                      width="{{ bar_width }}" height="{{ bar_h_venta }}"
                      fill="#FF6B15" rx="2"/>
                <!-- Valor encima barra venta -->
                {% if bar_h_venta > 12 %}
                <text x="{{ bar_x_venta + bar_width / 2 | int }}" y="{{ bar_y_venta - 3 }}"
                      text-anchor="middle" font-size="6.5" fill="#cc4a00" font-weight="bold">
                    {{ frappe.utils.fmt_money(venta_row, currency=doc.currency or "MXN") }}
                </text>
                {% endif %}

                <!-- Etiqueta producto en eje X -->
                {% set label_x = group_x + bar_width %}
                {% set label = (row.finished_item or ("Prod. " ~ loop.index)) %}
                {% set label_short = label[:14] ~ ("..." if label | length > 14 else "") %}
                <text x="{{ label_x }}" y="{{ padding_top + bar_area_height + 14 }}"
                      text-anchor="middle" font-size="7.5" fill="#555">
                    {{ label_short }}
                </text>
            {% endfor %}

            <!-- Leyenda -->
            <rect x="{{ padding_left }}" y="{{ svg_height - 14 }}"
                  width="10" height="10" fill="#FFAA77" rx="2"/>
            <text x="{{ padding_left + 13 }}" y="{{ svg_height - 5 }}"
                  font-size="8" fill="#666">Costo Total</text>

            <rect x="{{ padding_left + 80 }}" y="{{ svg_height - 14 }}"
                  width="10" height="10" fill="#FF6B15" rx="2"/>
            <text x="{{ padding_left + 93 }}" y="{{ svg_height - 5 }}"
                  font-size="8" fill="#666">Precio de Venta</text>

        </svg>
        </div>
    </div>
    {% endif %}

    <!-- TÉRMINOS Y CONDICIONES -->

    {{ oc.cierre(doc, "Documento interno de costeo.", mostrar_pagos=false) }}

</div>

{{ oc.membrete_pie(footer, no_letterhead, print_settings) }}
